import AxeBuilder from "@axe-core/playwright";
import { expect, type Page } from "@playwright/test";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

export const REPO = resolve(import.meta.dirname, "..", "..");
export const FIXTURE = (name: string) => join(REPO, "fixtures", "bin", name);
export const STATEMENT = "I built this fixture from Bytasm's own source in fixtures/src.";

/** A temp file holding bytes generated by the test (never committed, never run). */
export function tempFile(name: string, data: Buffer): string {
  const path = join(mkdtempSync(join(tmpdir(), "bytasm-e2e-")), name);
  writeFileSync(path, data);
  return path;
}

/** A modified copy of a fixture: same name, one byte different, so not in the manifest. */
export function modifiedFixture(name: string): string {
  const data = Buffer.from(readFileSync(FIXTURE(name)));
  data[data.length - 1] = data[data.length - 1]! ^ 0xff;
  return tempFile(name, data);
}

/** An x86-64 ELF fixture copy whose .comment section has an HTML-like name. */
export function hostileElf(name: string): string {
  const out = tempFile("hostile.elf", Buffer.alloc(0));
  const script = [
    "import sys",
    "from pathlib import Path",
    "sys.path.insert(0, 'tests')",
    "from generated_inputs import with_elf64_section_renamed",
    "data = Path(sys.argv[1]).read_bytes()",
    "Path(sys.argv[2]).write_bytes(with_elf64_section_renamed(data, b'.comment', sys.argv[3].encode()))",
  ].join("\n");
  execFileSync(
    "uv",
    ["--directory", join(REPO, "backend"), "run", "--no-sync", "python", "-c", script,
      FIXTURE("hello_v1-x86_64.elf"), out, name],
    { stdio: "inherit" },
  );
  return out;
}

export async function expectNoAxeViolations(page: Page) {
  // @axe-core/playwright types `page` against its own playwright-core copy.
  const options = { page } as unknown as ConstructorParameters<typeof AxeBuilder>[0];
  const results = await new AxeBuilder(options).withTags(["wcag2a", "wcag2aa", "wcag22aa"]).analyze();
  expect(results.violations.map((v) => `${v.id}: ${v.help}`)).toEqual([]);
}

export async function createProject(page: Page, base: string, name: string) {
  await page.goto(`${base}/`);
  await page.getByLabel("Name").fill(name);
  await page.getByRole("button", { name: "Create project" }).click();
  await expect(page.getByRole("heading", { level: 1, name })).toBeVisible();
}

export async function importFile(page: Page, path: string, options: { sample?: string; label?: string } = {}) {
  await page.getByRole("link", { name: "Import a binary" }).first().click();
  await expect(page.getByRole("heading", { name: "Import a binary" })).toBeVisible();
  await page.getByLabel("File").setInputFiles(path);
  if (options.sample) await page.getByLabel("Sample name").fill(options.sample);
  if (options.label) await page.getByLabel("Version label (optional)").fill(options.label);
  await page.getByLabel("Statement").fill(STATEMENT);
  await page.getByRole("button", { name: "Import" }).click();
}
